const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.processedMessageIds)) {
  staticData.processedMessageIds = [];
}

const item = $input.first().json;
const messageId = item.id || item.messageId;

if (!messageId) {
  throw new Error('Missing Gmail message id');
}

if (staticData.processedMessageIds.includes(messageId)) {
  return [];
}

staticData.processedMessageIds.push(messageId);
if (staticData.processedMessageIds.length > 500) {
  staticData.processedMessageIds = staticData.processedMessageIds.slice(-500);
}

const subject = item.subject || item.Subject || '';
const from = item.from || item.From || '';
const text = item.text || item.snippet || '';
const html = item.html || '';
const body = (text && String(text).trim())
  ? text
  : String(html).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

return [{
  json: {
    messageId,
    threadId: item.threadId,
    subject,
    from,
    emailBody: body,
    receivedAt: item.date || item.internalDate || new Date().toISOString(),
    labelIds: item.labelIds || []
  }
}];

