const email = $('Idempotency + Prepare Email').first().json;
const aiItem = $input.first().json;

let parsed = {};
try {
  if (typeof aiItem.message?.content === 'string') {
    parsed = JSON.parse(aiItem.message.content);
  } else if (aiItem.message?.content && typeof aiItem.message.content === 'object') {
    parsed = aiItem.message.content;
  } else if (aiItem.content && typeof aiItem.content === 'object' && !Array.isArray(aiItem.content)) {
    parsed = aiItem.content;
  } else if (typeof aiItem.content === 'string') {
    parsed = JSON.parse(aiItem.content);
  } else if (aiItem.projectType || aiItem.fitScore !== undefined) {
    parsed = aiItem;
  } else if (aiItem.output) {
    parsed = typeof aiItem.output === 'string' ? JSON.parse(aiItem.output) : aiItem.output;
  } else if (aiItem.text) {
    const raw = String(aiItem.text).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
    parsed = JSON.parse(raw);
  } else {
    const raw = JSON.stringify(aiItem);
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) parsed = JSON.parse(match[0]);
  }
} catch (e) {
  parsed = {};
}

const fitScore = Math.max(1, Math.min(10, Number(parsed.fitScore) || 1));
let leadQuality = parsed.leadQuality;
if (!leadQuality) {
  leadQuality = fitScore >= 7 ? 'High' : fitScore >= 4 ? 'Medium' : 'Low';
}

return [{
  json: {
    messageId: email.messageId,
    threadId: email.threadId,
    from: email.from,
    subject: email.subject,
    emailBody: email.emailBody,
    timestamp: new Date().toISOString(),
    projectType: parsed.projectType || 'Unknown',
    budgetRange: parsed.budgetRange || 'Unknown',
    timeline: parsed.timeline || 'Unknown',
    keyRequirements: parsed.keyRequirements || 'Unable to extract requirements',
    fitScore,
    leadQuality,
    aiFailed: false,
    errorMessage: ''
  }
}];

